export function sumTo(n) {
  let s = 0;
  for (let i = 1; i < n; i++) {
    s += i;
  }
  return s;
}

import { sumTo } from './solution.mjs';
import assert from 'node:assert';
assert.strictEqual(sumTo(1), 1, 'n=1 应为 1');
assert.strictEqual(sumTo(10), 55, 'n=10 应为 55');
assert.strictEqual(sumTo(100), 5050, 'n=100 应为 5050');
console.log('ALL TESTS PASSED');
